//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
//	NAME:					HE_NX_AD_Module
//	CREATOR:				Helgevold - William Veim
// REQUIREMENTS: NX CPU
//
// DESCRTIPTION: 	Decodes parameter data, based on spesific NX DA (Omron NX analog output) module
//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
//  VERSION LOG:
//	 VERSION			DATE				SIGN						DESCRIPTION
//	 1.0.0				2025-07-07		William Veim			Initial release
//
//================================================================================================================================

CASE Cfg_R3_AD_Module OF
	
	R3_SC4AS_100_100mV:
		Out_SignalValue_Unit:= 			'mV';
		Out_SignalValue_Y0:=				-100;
		Out_SignalValue_Y1:=				100;
		Out_SignalValue_Min:= 			-100;
		Out_SignalValue_Max:= 			100;
		Out_RawValue_X0:= 				0;
		Out_RawValue_X1:= 				10000;
		Out_RawValue_Min:=      		0;
		Out_RawValue_Max:=				10000;
		Out_RawValue_LoopBreak := 	16#7FFF;
		
	R3_SC4AS_60_60mV:	
		Out_SignalValue_Unit:= 			'mV';
		Out_SignalValue_Y0:=				-60;
		Out_SignalValue_Y1:=				60;
		Out_SignalValue_Min:= 			-60;
		Out_SignalValue_Max:= 			60;
		Out_RawValue_X0:= 				0;
		Out_RawValue_X1:= 				10000;
		Out_RawValue_Min:=      		0;
		Out_RawValue_Max:=				10000;
		Out_RawValue_LoopBreak := 	16#7FFF;
		
	R3_SC4AS_50_50mV:	
		Out_SignalValue_Unit:= 			'mV';
		Out_SignalValue_Y0:=				-50;
		Out_SignalValue_Y1:=				50;
		Out_SignalValue_Min:= 			-50;
		Out_SignalValue_Max:= 			50;
		Out_RawValue_X0:= 				0;
		Out_RawValue_X1:= 				10000;
		Out_RawValue_Min:=      		0;
		Out_RawValue_Max:=				10000;
		Out_RawValue_LoopBreak := 	16#7FFF;
		
	R3_SC4AS_0_100mV:
		Out_SignalValue_Unit:= 			'mV';
		Out_SignalValue_Y0:=				0;
		Out_SignalValue_Y1:=				100;
		Out_SignalValue_Min:= 			0;
		Out_SignalValue_Max:= 			100;
		Out_RawValue_X0:= 				0;
		Out_RawValue_X1:= 				10000;
		Out_RawValue_Min:=      		0;
		Out_RawValue_Max:=				10000;
		Out_RawValue_LoopBreak := 	16#7FFF;
		
	R3_SC4AS_0_60mV:
		Out_SignalValue_Unit:= 			'mV';
		Out_SignalValue_Y0:=				0;
		Out_SignalValue_Y1:=				60;
		Out_SignalValue_Min:= 			0;
		Out_SignalValue_Max:= 			60;
		Out_RawValue_X0:= 				0;
		Out_RawValue_X1:= 				10000;
		Out_RawValue_Min:=      		0;
		Out_RawValue_Max:=				10000;
		Out_RawValue_LoopBreak := 	16#7FFF;
		
	R3_SC4AS_0_50mV:
		Out_SignalValue_Unit:= 			'mV';
		Out_SignalValue_Y0:=				0;
		Out_SignalValue_Y1:=				50;
		Out_SignalValue_Min:= 			0;
		Out_SignalValue_Max:= 			50;
		Out_RawValue_X0:= 				0;
		Out_RawValue_X1:= 				10000;
		Out_RawValue_Min:=      		0;
		Out_RawValue_Max:=				10000;
		Out_RawValue_LoopBreak := 	16#7FFF;
		
END_CASE;
